<?php
/* phpLDAPadmin for the Acme Insurance directory (slapd in the same container).
 * Full option list: /usr/share/phpldapadmin/config/config.php.example */

// Cookie encryption secret, generated by entrypoint.sh on every start.
$config->custom->session['blowfish'] = trim(file_get_contents('/run/phpldapadmin/blowfish'));
$config->custom->appearance['timezone'] = 'UTC';
$config->custom->appearance['hide_template_warning'] = true;
$config->custom->appearance['friendly_attrs'] = array(
    'acmeUserType' => 'User type',
    'acmeAccountDN' => 'Account grant',
    'acmeFeatureDN' => 'Feature grant',
    'acmePolicyNumber' => 'Policy number',
    'acmeSalesforceId' => 'Salesforce ID',
    'acmeSource' => 'Sync source',
);

$servers = new Datastore();
$servers->newServer('ldap_pla');
$servers->setValue('server', 'name', 'Acme Insurance');
// Host as a URI with port 0: phpLDAPadmin then calls ldap_connect() with one
// argument (the two-argument form is deprecated in PHP 8.3 and its error
// handler would turn the notice into an error page).
$servers->setValue('server', 'host', 'ldap://127.0.0.1:1389');
$servers->setValue('server', 'port', 0);
$servers->setValue('server', 'base', array('dc=acmeinsurance,dc=com'));
$servers->setValue('login', 'auth_type', 'cookie');
$servers->setValue('login', 'anon_bind', false);
// Pre-filled login; any DN with a password (e.g. svc-sync) can sign in instead.
$servers->setValue('login', 'bind_id', 'cn=admin,dc=acmeinsurance,dc=com');
// Send passwords in clear text over the in-container connection: slapd hashes
// them with Argon2 (olcPPolicyHashCleartext) and applies the password policy.
// phpLDAPadmin's own default would store an MD5 hash.
$servers->setValue('appearance', 'pla_password_hash', '');
// Entries the sync owns are overwritten by the next run; see README.
